const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Артиклі</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Німецький артикль не завжди збігається з родом слова в українській мові. Тому іменники найкраще вивчати разом з артиклем.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Приклади артиклів</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — стіл</div>\n      <div class=\"kurss-example\">die Tür — двері</div>\n      <div class=\"kurss-example\">das Messer — ніж</div>\n      <div class=\"kurss-example\">das Mädchen — дівчинка</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Часто DER</h4>\n    <p class=\"artikuli-explain\">DER часто мають особи чоловічої статі, дні, місяці, пори року та деякі слова з певними закінченнями.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → часто DER, наприклад: der Computer, der Lehrer <span class=\"artikuli-note\">але не завжди</span></div>\n      <div class=\"kurss-example\">-ling → часто DER, наприклад: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → часто DER, наприклад: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">особи чоловічої статі → der Mann, der Vater</div>\n      <div class=\"kurss-example\">професії → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">марки автомобілів → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">дні → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">місяці → der August, der Dezember</div>\n      <div class=\"kurss-example\">пори року → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Приклади</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — чоловік</div>\n      <div class=\"kurss-example\">der Vater — батько</div>\n      <div class=\"kurss-example\">der Montag — понеділок</div>\n      <div class=\"kurss-example\">der August — серпень</div>\n      <div class=\"kurss-example\">der Sommer — літо</div>\n      <div class=\"kurss-example\">der Lehrer — учитель</div>\n      <div class=\"kurss-example\">der Computer — комп’ютер</div>\n      <div class=\"kurss-example\">der Schmetterling — метелик</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Часто DIE</h4>\n    <p class=\"artikuli-explain\">DIE часто мають особи жіночої статі, множина та слова із закінченнями -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">особи жіночої статі → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">марки мотоциклів → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">множина → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">множина майже завжди → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Приклади</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — жінка</div>\n      <div class=\"kurss-example\">die Mutter — мати</div>\n      <div class=\"kurss-example\">die Wohnung — квартира</div>\n      <div class=\"kurss-example\">die Rechnung — рахунок</div>\n      <div class=\"kurss-example\">die Freiheit — свобода</div>\n      <div class=\"kurss-example\">die Möglichkeit — можливість</div>\n      <div class=\"kurss-example\">die Mannschaft — команда</div>\n      <div class=\"kurss-example\">die Nation — нація</div>\n      <div class=\"kurss-example\">die Universität — університет</div>\n      <div class=\"kurss-example\">die Polizei — поліція</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Часто DAS</h4>\n    <p class=\"artikuli-explain\">DAS часто мають зменшувальні слова на -chen / -lein, багато слів на -ment / -um та дієслова, вжиті як іменники.</p>\n\n    <h5 class=\"artikuli-subtitle\">Правила</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">метали → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">хімічні елементи → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">готелі → das Hotel</div>\n      <div class=\"kurss-example\">кольори як іменники → das Rot, das Blau</div>\n      <div class=\"kurss-example\">дієслово як іменник → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">дієслова як іменники → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Приклади</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — дитина</div>\n      <div class=\"kurss-example\">das Mädchen — дівчинка</div>\n      <div class=\"kurss-example\">das Häuschen — будиночок</div>\n      <div class=\"kurss-example\">das Instrument — інструмент</div>\n      <div class=\"kurss-example\">das Zentrum — центр</div>\n      <div class=\"kurss-example\">das Museum — музей</div>\n      <div class=\"kurss-example\">das Essen — їжа / прийом їжі</div>\n      <div class=\"kurss-example\">das Lernen — навчання</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Важливі винятки / слова, які треба вчити з артиклем</h4>\n    <p class=\"artikuli-explain\">Для деяких слів артикль не можна надійно визначити за закінченням або за родом слова в українській мові. Їх найкраще вивчати разом з артиклем.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — двері</div>\n      <div class=\"kurss-example\">das Messer — ніж</div>\n      <div class=\"kurss-example\">die Sonne — сонце</div>\n      <div class=\"kurss-example\">der Mond — місяць</div>\n      <div class=\"kurss-example\">das Mädchen — дівчинка</div>\n      <div class=\"kurss-example\">das Auto — автомобіль</div>\n      <div class=\"kurss-example\">der Käse — сир</div>\n      <div class=\"kurss-example\">die Gabel — виделка</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Закінчення та групи слів допомагають вгадати артикль, але це не стовідсоткове правило. Якщо не впевнений, вивчай слово разом з артиклем.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Займенники</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ і Dativ — форми займенників.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — хто? що?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — я</div><div class=\"kurss-example\">du — ти</div><div class=\"kurss-example\">er — він</div><div class=\"kurss-example\">sie — вона</div><div class=\"kurss-example\">es — воно</div><div class=\"kurss-example\">wir — ми</div><div class=\"kurss-example\">ihr — ви</div><div class=\"kurss-example\">sie — вони</div><div class=\"kurss-example\">Sie — Ви (ввічлива форма)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — кого? що?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — мене</div><div class=\"kurss-example\">dich — тебе</div><div class=\"kurss-example\">ihn — його (ч. р.)</div><div class=\"kurss-example\">sie — її (ж. р.)</div><div class=\"kurss-example\">es — його (с. р.)</div><div class=\"kurss-example\">uns — нас</div><div class=\"kurss-example\">euch — вас</div><div class=\"kurss-example\">sie — їх</div><div class=\"kurss-example\">Sie — Вас (ввічлива форма)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — кому?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — мені</div><div class=\"kurss-example\">dir — тобі</div><div class=\"kurss-example\">ihm — йому</div><div class=\"kurss-example\">ihr — їй</div><div class=\"kurss-example\">uns — нам</div><div class=\"kurss-example\">euch — вам</div><div class=\"kurss-example\">ihnen — їм</div><div class=\"kurss-example\">Ihnen — Вам (ввічлива форма)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Як вибрати форму?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — підмет (хто діє?)</li><li><span class=\"case-red\">Akkusativ</span> — прямий додаток (кого? що?)</li><li><span class=\"case-green\">Dativ</span> — непрямий додаток (кому?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Приклади</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Я бачу тебе.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Я бачу його.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Ви нам подобаєтеся.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Я допомагаю тобі.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Я даю йому книжку.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Ми дякуємо вам.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ завжди є підметом речення, а Akkusativ і Dativ — додатками. Дивись на дієслово й запитуй: <span class=\"case-red\">кого? що?</span> або <span class=\"case-green\">кому?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Голосні — довгі та короткі</h3>\n            <p class=\"kurss-lesson-intro\">У німецькій мові голосні можуть бути довгими або короткими. Це впливає на вимову слова.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Довгий голосний</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (варм) — теплий</div><div class=\"kurss-example\">gut (гӯт) — добрий / хороший</div><div class=\"kurss-example\">Tat (та̄т) — вчинок / дія</div><div class=\"kurss-example\">Flur (флӯр) — коридор</div><div class=\"kurss-example\">Weg (ве̄к) — дорога / шлях</div><div class=\"kurss-example\">Hut (гӯт) — капелюх</div><div class=\"kurss-example\">Hof (го̄ф) — двір</div><div class=\"kurss-example\">Schlaf (шла̄ф) — сон</div></div>\n              <p>Якщо після голосного стоїть один приголосний, голосний часто вимовляється довго.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Короткий голосний</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (пільц) — гриб</div><div class=\"kurss-example\">Wort (ворт) — слово</div><div class=\"kurss-example\">Mund (мунт) — рот</div><div class=\"kurss-example\">bald (бальт) — скоро</div><div class=\"kurss-example\">scharf (шарф) — гострий</div><div class=\"kurss-example\">Feld (фельт) — поле</div><div class=\"kurss-example\">voll (фол) — повний</div></div>\n              <p>Якщо після голосного стоять два або більше приголосних, голосний часто вимовляється коротко.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Закінчення en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (зінґен) — співати</div><div class=\"kurss-example\">tragen (тра̄ґен) — нести / носити</div><div class=\"kurss-example\">Garten (ґартен) — сад</div><div class=\"kurss-example\">Vogel (фо̄ґель) — птах</div><div class=\"kurss-example\">Segel (зе̄ґель) — вітрило</div><div class=\"kurss-example\">Braten (бра̄тен) — печеня</div><div class=\"kurss-example\">Bogen (бо̄ґен) — дуга / лук</div><div class=\"kurss-example\">Spiegel (шпі̄ґель) — дзеркало</div><div class=\"kurss-example\">Finger (фінґер) — палець</div><div class=\"kurss-example\">Halter (гальтер) — тримач</div><div class=\"kurss-example\">Arbeiter (арбайтер) — робітник</div><div class=\"kurss-example\">Häuser (гойзер) — будинки</div><div class=\"kurss-example\">wieder (ві̄дер) — знову</div><div class=\"kurss-example\">breiter (брайтер) — ширший</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Літера h як знак довготи</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (ра̄мен) — рама / рамка</div><div class=\"kurss-example\">Ohr (о̄р) — вухо</div><div class=\"kurss-example\">Kohle (ко̄ле) — вугілля</div><div class=\"kurss-example\">Zahl (ца̄ль) — число</div><div class=\"kurss-example\">ihn (і̄н) — його</div><div class=\"kurss-example\">ihm (і̄м) — йому</div><div class=\"kurss-example\">Huhn (гӯн) — курка</div><div class=\"kurss-example\">nahm (на̄м) — взяв</div><div class=\"kurss-example\">nehmen (не̄мен) — брати</div><div class=\"kurss-example\">Schuh (шӯ) — черевик</div></div>\n              <p>У деяких словах h подовжує попередній голосний. У таких випадках h зазвичай не вимовляється.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Закінчення на e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (лампе) — лампа</div><div class=\"kurss-example\">Hase (га̄зе) — заєць</div><div class=\"kurss-example\">Knabe (кна̄бе) — хлопчик</div><div class=\"kurss-example\">Rabe (ра̄бе) — ворон</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Довге i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (ді̄) — артикль «die»</div><div class=\"kurss-example\">diese (ді̄зе) — ця / ці</div><div class=\"kurss-example\">wieder (ві̄дер) — знову</div><div class=\"kurss-example\">Fliege (флі̄ґе) — муха</div><div class=\"kurss-example\">Ziege (ці̄ґе) — коза</div><div class=\"kurss-example\">Stiel (шті̄ль) — стебло / держак</div><div class=\"kurss-example\">Dieb (ді̄п) — злодій</div><div class=\"kurss-example\">hier (гі̄р) — тут</div></div>\n              <p>Довге i в німецькій мові часто пишеться як ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Подвоєні голосні</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (за̄ль) — зала</div><div class=\"kurss-example\">Saat (за̄т) — посів / насіння</div><div class=\"kurss-example\">Staat (шта̄т) — держава</div><div class=\"kurss-example\">Beere (бе̄ре) — ягода</div><div class=\"kurss-example\">See (зе̄) — озеро / море</div><div class=\"kurss-example\">Beet (бе̄т) — грядка</div><div class=\"kurss-example\">Boot (бо̄т) — човен</div><div class=\"kurss-example\">Moor (мо̄р) — болото</div><div class=\"kurss-example\">Moos (мо̄с) — мох</div></div>\n              <p>Подвоєні голосні зазвичай вимовляються довго.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (вант) — стіна</div><div class=\"kurss-example\">Wände (венде) — стіни</div><div class=\"kurss-example\">Vater (фа̄тер) — батько</div><div class=\"kurss-example\">Väter (фе̄тер) — батьки (тати)</div><div class=\"kurss-example\">Schrank (шранк) — шафа</div><div class=\"kurss-example\">Schränke (шренке) — шафи</div><div class=\"kurss-example\">Bank (банк) — лавка / банк</div><div class=\"kurss-example\">Bänke (бенке) — лавки</div><div class=\"kurss-example\">Tal (та̄ль) — долина</div><div class=\"kurss-example\">Täler (те̄лер) — долини</div></div>\n              <p>ä — це умлаут (перегласівка) від a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (ро̄зе) — троянда</div><div class=\"kurss-example\">Röschen (ре̄схен) — трояндочка</div><div class=\"kurss-example\">Ofen (о̄фен) — піч</div><div class=\"kurss-example\">Öfen (е̄фен) — печі</div><div class=\"kurss-example\">Rock (рок) — спідниця</div><div class=\"kurss-example\">Röcke (реке) — спідниці</div></div>\n              <p>ö — це умлаут (перегласівка) від o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (курц) — короткий</div><div class=\"kurss-example\">kürzer (кюрцер) — коротший</div><div class=\"kurss-example\">Kunst (кунст) — мистецтво</div><div class=\"kurss-example\">Künste (кюнсте) — мистецтва</div><div class=\"kurss-example\">Mutter (мутер) — мати</div><div class=\"kurss-example\">Mütter (мютер) — матері</div></div>\n              <p>ü — це умлаут (перегласівка) від u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (баум) — дерево</div><div class=\"kurss-example\">Bäume (бойме) — дерева</div><div class=\"kurss-example\">Haus (гаус) — будинок</div><div class=\"kurss-example\">Häuser (гойзер) — будинки</div><div class=\"kurss-example\">Strauch (штраух) — кущ</div><div class=\"kurss-example\">Sträucher (штройхер) — кущі</div><div class=\"kurss-example\">Maus (маус) — миша</div><div class=\"kurss-example\">Mäuse (мойзе) — миші</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (гойте) — сьогодні</div><div class=\"kurss-example\">Leute (лойте) — люди</div><div class=\"kurss-example\">neu (ной) — новий</div><div class=\"kurss-example\">neun (нойн) — дев’ять</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дифтонги: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (майн) — мій</div><div class=\"kurss-example\">dein (дайн) — твій</div><div class=\"kurss-example\">sein (зайн) — його / бути</div><div class=\"kurss-example\">frei (фрай) — вільний</div><div class=\"kurss-example\">arbeiten (арбайтен) — працювати</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Примітки щодо вимови до 2-го заняття</h4>\n              <ul class=\"kurss-summary-list\"><li>у словах ich, nicht, rechnen, zeichnen «ch» вимовляється м’яко (близько до м’якого українського «хь»)</li><li>у словах arbeiten і zeichnen «ei» вимовляється як «ай»</li><li>«sp» на початку слова вимовляється як «шп»</li><li>у дієслові tun літера «u» вимовляється довго</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Підсумок</h4>\n              <ul class=\"kurss-summary-list\"><li>один приголосний після голосного → часто довгий голосний</li><li>два або більше приголосних → часто короткий голосний</li><li>h може подовжувати голосний</li><li>ie часто означає довге i</li><li>подвоєні голосні зазвичай довгі</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Приголосні та літерні поєднання</h3>\n            <p class=\"kurss-lesson-intro\">У німецькій мові деякі приголосні та поєднання літер вимовляються інакше, ніж пишуться. У цьому занятті — найважливіші приклади для початківців.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Приголосні</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (дас ра̄т) — колесо</div><div class=\"kurss-example\">die Räder (ді ре̄дер) — колеса</div><div class=\"kurss-example\">Bad (ба̄т) — ванна / купання</div><div class=\"kurss-example\">Bäder (бе̄дер) — ванни</div></div>\n              <p>У кінці слова приголосні часто вимовляються не так, як пишуться (наприклад, d звучить як «т»).</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>«ch» може вимовлятися м’яко або твердо. У деяких словах воно звучить як м’яке «хь», в інших — як тверде українське «х».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (рехнен) — рахувати / обчислювати</div><div class=\"kurss-example\">zeichnen (цайхнен) — малювати / креслити</div><div class=\"kurss-example\">nicht (ніхт) — не</div><div class=\"kurss-example\">schlecht (шлехт) — поганий</div><div class=\"kurss-example\">mich (міх) — мене</div><div class=\"kurss-example\">dich (діх) — тебе</div><div class=\"kurss-example\">Strauch (штраух) — кущ</div><div class=\"kurss-example\">noch (нох) — ще</div><div class=\"kurss-example\">Nacht (нахт) — ніч</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>«sch» у німецькій мові вимовляється як українське «ш».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (шӯле) — школа</div><div class=\"kurss-example\">Schüler (шю̄лер) — учень</div><div class=\"kurss-example\">Schiff (шіф) — корабель</div><div class=\"kurss-example\">Schraube (шраубе) — гвинт / шуруп</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp і st на початку слова</h4>\n              <p>На початку слова або складу «sp» часто вимовляється як «шп», а «st» — як «шт».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (шпі̄лен) — грати</div><div class=\"kurss-example\">Sprung (шпрунґ) — стрибок</div><div class=\"kurss-example\">stehen (ште̄ен) — стояти</div><div class=\"kurss-example\">Stall (шталь) — хлів / стайня</div><div class=\"kurss-example\">Stand (штант) — стан / місце</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>«qu» у німецькій мові зазвичай вимовляється як «кв».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (ква̄ль) — мука / страждання</div><div class=\"kurss-example\">Quartier (кварті̄р) — житло / квартал</div><div class=\"kurss-example\">quer (кве̄р) — поперек</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s і z</h4>\n              <p>На початку слова «s» часто звучить як «з». Літера «z» у німецькій мові звучить як українське «ц».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (за̄ґен) — казати</div><div class=\"kurss-example\">singen (зінґен) — співати</div><div class=\"kurss-example\">Rose (ро̄зе) — троянда</div><div class=\"kurss-example\">Zahl (ца̄ль) — число</div><div class=\"kurss-example\">Zeit (цайт) — час</div><div class=\"kurss-example\">Zink (цінк) — цинк</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>У німецькій мові «v» часто вимовляється як «ф». У запозичених словах воно часто звучить як українське «в».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (фа̄тер) — батько</div><div class=\"kurss-example\">von (фон) — від / з</div><div class=\"kurss-example\">viel (фі̄ль) — багато</div><div class=\"kurss-example\">vier (фі̄р) — чотири</div><div class=\"kurss-example\">Villa (вілла) — вілла</div><div class=\"kurss-example\">Klavier (клаві̄р) — фортепіано / піаніно</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x і y</h4>\n              <p>«x» вимовляється як «кс». «y» у деяких словах вимовляється як «ü» (приблизно як «ю»).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (фе̄лікс) — Фелікс</div><div class=\"kurss-example\">Axt (акст) — сокира</div><div class=\"kurss-example\">Mystik (мюстік) — містика</div><div class=\"kurss-example\">Mythe (мю̄те) — міф</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>«ß» у німецькій мові вимовляється як «с».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (фӯс) — стопа / нога</div><div class=\"kurss-example\">Füße (фю̄се) — стопи / ноги</div><div class=\"kurss-example\">Grüße (ґрю̄се) — вітання</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Підсумок</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → ш</li><li>sp / st на початку → шп / шт</li><li>qu → кв</li><li>z → ц</li><li>v часто → ф</li><li>x → кс</li><li>ß → с</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Основи дієслів</h3>\n            <p class=\"kurss-lesson-intro\">Дієслова 1-го уроку та їхні форми (дієвідмінювання)</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Дієслова</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — приходити</div><div class=\"kurss-example\">gehen — іти</div><div class=\"kurss-example\">stehen — стояти</div><div class=\"kurss-example\">singen — співати</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — я приходжу</div><div class=\"kurss-example\">du kommst — ти приходиш</div><div class=\"kurss-example\">er kommt — він приходить</div><div class=\"kurss-example\">sie kommt — вона приходить</div><div class=\"kurss-example\">wir kommen — ми приходимо</div><div class=\"kurss-example\">ihr kommt — ви приходите</div><div class=\"kurss-example\">sie kommen — вони приходять</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — я іду</div><div class=\"kurss-example\">du gehst — ти ідеш</div><div class=\"kurss-example\">er geht — він іде</div><div class=\"kurss-example\">sie geht — вона іде</div><div class=\"kurss-example\">wir gehen — ми ідемо</div><div class=\"kurss-example\">ihr geht — ви ідете</div><div class=\"kurss-example\">sie gehen — вони ідуть</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — я стою</div><div class=\"kurss-example\">du stehst — ти стоїш</div><div class=\"kurss-example\">er steht — він стоїть</div><div class=\"kurss-example\">sie steht — вона стоїть</div><div class=\"kurss-example\">wir stehen — ми стоїмо</div><div class=\"kurss-example\">ihr steht — ви стоїте</div><div class=\"kurss-example\">sie stehen — вони стоять</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — я співаю</div><div class=\"kurss-example\">du singst — ти співаєш</div><div class=\"kurss-example\">er singt — він співає</div><div class=\"kurss-example\">sie singt — вона співає</div><div class=\"kurss-example\">wir singen — ми співаємо</div><div class=\"kurss-example\">ihr singt — ви співаєте</div><div class=\"kurss-example\">sie singen — вони співають</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Дієслова 2-го уроку</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — грати</div><div class=\"kurss-example\">arbeiten — працювати</div><div class=\"kurss-example\">fragen — питати</div><div class=\"kurss-example\">antworten — відповідати</div><div class=\"kurss-example\">rechnen — рахувати</div><div class=\"kurss-example\">zeichnen — малювати</div><div class=\"kurss-example\">tun — робити</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — я граю</div><div class=\"kurss-example\">du spielst — ти граєш</div><div class=\"kurss-example\">er spielt — він грає</div><div class=\"kurss-example\">sie spielt — вона грає</div><div class=\"kurss-example\">wir spielen — ми граємо</div><div class=\"kurss-example\">ihr spielt — ви граєте</div><div class=\"kurss-example\">sie spielen — вони грають</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — я працюю</div><div class=\"kurss-example\">du arbeitest — ти працюєш</div><div class=\"kurss-example\">er arbeitet — він працює</div><div class=\"kurss-example\">sie arbeitet — вона працює</div><div class=\"kurss-example\">wir arbeiten — ми працюємо</div><div class=\"kurss-example\">ihr arbeitet — ви працюєте</div><div class=\"kurss-example\">sie arbeiten — вони працюють</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — я питаю</div><div class=\"kurss-example\">du fragst — ти питаєш</div><div class=\"kurss-example\">er fragt — він питає</div><div class=\"kurss-example\">sie fragt — вона питає</div><div class=\"kurss-example\">wir fragen — ми питаємо</div><div class=\"kurss-example\">ihr fragt — ви питаєте</div><div class=\"kurss-example\">sie fragen — вони питають</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — я відповідаю</div><div class=\"kurss-example\">du antwortest — ти відповідаєш</div><div class=\"kurss-example\">er antwortet — він відповідає</div><div class=\"kurss-example\">sie antwortet — вона відповідає</div><div class=\"kurss-example\">wir antworten — ми відповідаємо</div><div class=\"kurss-example\">ihr antwortet — ви відповідаєте</div><div class=\"kurss-example\">sie antworten — вони відповідають</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — я рахую</div><div class=\"kurss-example\">du rechnest — ти рахуєш</div><div class=\"kurss-example\">er rechnet — він рахує</div><div class=\"kurss-example\">sie rechnet — вона рахує</div><div class=\"kurss-example\">wir rechnen — ми рахуємо</div><div class=\"kurss-example\">ihr rechnet — ви рахуєте</div><div class=\"kurss-example\">sie rechnen — вони рахують</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — я малюю</div><div class=\"kurss-example\">du zeichnest — ти малюєш</div><div class=\"kurss-example\">er zeichnet — він малює</div><div class=\"kurss-example\">sie zeichnet — вона малює</div><div class=\"kurss-example\">wir zeichnen — ми малюємо</div><div class=\"kurss-example\">ihr zeichnet — ви малюєте</div><div class=\"kurss-example\">sie zeichnen — вони малюють</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — я роблю</div><div class=\"kurss-example\">du tust — ти робиш</div><div class=\"kurss-example\">er tut — він робить</div><div class=\"kurss-example\">sie tut — вона робить</div><div class=\"kurss-example\">wir tun — ми робимо</div><div class=\"kurss-example\">ihr tut — ви робите</div><div class=\"kurss-example\">sie tun — вони роблять</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Будова речення</h3>\n            <p class=\"kurss-lesson-intro\">У питальному реченні дієслово в німецькій мові зазвичай стоїть на першому місці.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Приклади</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Ти приходиш.</div><div class=\"kurss-example\">Kommst du? — Ти приходиш?</div><div class=\"kurss-example\">Er singt. — Він співає.</div><div class=\"kurss-example\">Singt er? — Він співає?</div><div class=\"kurss-example\">Stehst du? — Ти стоїш?</div><div class=\"kurss-example\">Ja, ich stehe. — Так, я стою.</div><div class=\"kurss-example\">Geht ihr? — Ви йдете?</div><div class=\"kurss-example\">Ja, wir gehen. — Так, ми йдемо.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Питання з «was»</h4>\n              <p>Якщо питання починається з питального слова, дієслово в німецькій мові зазвичай стоїть одразу після питального слова.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Що ти робиш?</div><div class=\"kurss-example\">Was tut er? — Що він робить?</div><div class=\"kurss-example\">Was tut sie? — Що вона робить?</div><div class=\"kurss-example\">Was tun sie? — Що вони роблять?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Заперечення з «nicht»</h4>\n              <p>Якщо заперечення «nicht» стосується дієслова, то в німецькій мові воно зазвичай стоїть після дієслова.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Я не граю.</div><div class=\"kurss-example\">Paul fragt nicht. — Пауль не питає.</div><div class=\"kurss-example\">Er kommt nicht. — Він не приходить.</div><div class=\"kurss-example\">Sie singen nicht. — Вони не співають.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Речення з 2-го уроку</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Ти граєш?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Ні, я не граю, я працюю.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Пауль не питає, він працює.</div><div class=\"kurss-example\">Arbeitest du? — Ти працюєш?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Ні, я не працюю, я співаю.</div><div class=\"kurss-example\">Was tut Paul? — Що робить Пауль?</div><div class=\"kurss-example\">Er spielt. — Він грає.</div><div class=\"kurss-example\">Was tut Marie? — Що робить Марі?</div><div class=\"kurss-example\">Sie singt. — Вона співає.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Пауль грає, а Марі співає.</div><div class=\"kurss-example\">Singt ihr? — Ви співаєте?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Ні, ми не співаємо, ми працюємо.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Що роблять Пауль і Марі?</div><div class=\"kurss-example\">Sie fragen. — Вони питають.</div><div class=\"kurss-example\">Sie antworten nicht. — Вони не відповідають.</div><div class=\"kurss-example\">Wer arbeitet? — Хто працює?</div><div class=\"kurss-example\">Wir arbeiten. — Ми працюємо.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Ми рахуємо і малюємо.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Вони приходять, питають, відповідають, працюють, грають, співають і йдуть.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Урок 2</h3>\n            <p class=\"kurss-lesson-intro\">Другий урок: діалоги, слова, вимова, граматика й переклад.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — гратися; грати</div>\n                  <div class=\"kurss-example\">nein — ні</div>\n                  <div class=\"kurss-example\">nicht — не</div>\n                  <div class=\"kurss-example\">arbeiten — працювати</div>\n                  <div class=\"kurss-example\">fragen — питати</div>\n                  <div class=\"kurss-example\">was tut er? — що він робить?</div>\n                  <div class=\"kurss-example\">was tun sie? — що вони роблять?</div>\n                  <div class=\"kurss-example\">aber — але</div>\n                  <div class=\"kurss-example\">antworten — відповідати</div>\n                  <div class=\"kurss-example\">rechnen — рахувати</div>\n                  <div class=\"kurss-example\">zeichnen — малювати</div>\n                  <div class=\"kurss-example\">Marie — Марія</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">У словах ich, nicht, rechnen, zeichnen звук ch вимовляють м'яко, приблизно як українське м'яке х у словах: хімія, хірург.</div><div class=\"kurss-example\">У словах arbeiten, zeichnen дифтонг ei вимовляють приблизно як українське «ай».</div><div class=\"kurss-example\">Сполучення приголосних sp вимовляють як шп: spielen (шпі́лен).</div><div class=\"kurss-example\">У дієслові tun звук u вимовляють довго в усіх особах.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Закінчення з e</h4>\n                  <div class=\"lesson1-grammar-note\">Якщо основа дієслова закінчується на t, d, chn, то під час відмінювання перед закінченнями -st і -t стоїть e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Питальне слово</h4>\n                  <div class=\"lesson1-grammar-note\">У питальних реченнях, що починаються з питального слова, наприклад: що? хто? який? чому? навіщо? тощо, дієслово стоїть одразу після питального слова.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Що ти робиш?</div><div class=\"kurss-example\">Was tut er? — Що він робить?</div><div class=\"kurss-example\">Was tut sie? — Що вона робить?</div><div class=\"kurss-example\">Was tun sie? — Що вони роблять?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Заперечення з nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Якщо заперечення nicht стосується дієслова, то заперечне слово стоїть після дієслова.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Він не приходить.</div><div class=\"kurss-example\">Sie singen nicht. — Вони не співають.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переклади</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 2: картка для перекладу\">\n                    <span class=\"lesson1-training-progress\">Урок 2 · Переклади: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Хто питає?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Натисни на картку, щоб побачити переклад німецькою. Після відповіді наступне натискання покаже наступну картку.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Урок 6</h3>\n    <p class=\"kurss-lesson-intro\">Числівники, множина, умлаути та форми множини іменників.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — знаходиться, є, лежить</div><div class=\"kurss-example\">der Bleistift (блайштіфт) — олівець</div><div class=\"kurss-example\">einige (айніґе) — кілька, деякі</div><div class=\"kurss-example\">hinlegen — покласти</div><div class=\"kurss-example\">legt hin — кладе</div><div class=\"kurss-example\">wieder (ві́дер) — знову</div><div class=\"kurss-example\">aufmachen — відкрити</div><div class=\"kurss-example\">er macht auf — він відкриває</div><div class=\"kurss-example\">anspitzen (аншпіцен) — загострити</div><div class=\"kurss-example\">er spitzt an — він загострює</div><div class=\"kurss-example\">sich setzen — сісти</div><div class=\"kurss-example\">setzt sich — сідає</div><div class=\"kurss-example\">der Schlüssel (шлю́сель) — ключ</div><div class=\"kurss-example\">das Fenster (фенстер) — вікно</div><div class=\"kurss-example\">die Tafel (ді́ та́фель) — дошка</div><div class=\"kurss-example\">der Garten — сад</div><div class=\"kurss-example\">der Löffel — ложка</div><div class=\"kurss-example\">zählen (це́лен) — лічити</div><div class=\"kurss-example\">die Nadel — голка</div><div class=\"kurss-example\">was ist das — що це?</div><div class=\"kurss-example\">der Hammer — молоток</div><div class=\"kurss-example\">die Hämmer — молотки</div><div class=\"kurss-example\">der Deckel (де́р декель) — кришка</div><div class=\"kurss-example\">der Teller — тарілка</div><div class=\"kurss-example\">der Wagen — віз</div><div class=\"kurss-example\">der Schlitten — сани</div><div class=\"kurss-example\">das Ding — річ</div><div class=\"kurss-example\">die Dinge — речі</div><div class=\"kurss-example\">wie sind die Dinge? — які ці речі?</div><div class=\"kurss-example\">voll (фол) — повний</div><div class=\"kurss-example\">leer (ле́р) — порожній</div><div class=\"kurss-example\">schwer (шве́р) — важкий, складний</div><div class=\"kurss-example\">leicht — легкий</div><div class=\"kurss-example\">der Eimer — відро</div><div class=\"kurss-example\">wieviel (ві́фі́ль) — скільки</div><div class=\"kurss-example\">wieviel Nadeln — скільки голок</div><div class=\"kurss-example\">hier (гі́р) — тут</div><div class=\"kurss-example\">dort — там</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä позначає умлаут голосного a, і його вимовляють як короткий або довгий закритий е.</div><div class=\"kurss-example\">Приклади: das Mädchen (ме́тхен), die Bänke (ді́ бенке), der Vater (де́р фа́тер), die Väter (ді́ фе́тер).</div><div class=\"kurss-example\">ü позначає умлаут голосного u. Вимовляючи його, треба сильно заокруглити губи й намагатися з такими губами вимовити і.</div><div class=\"kurss-example\">Приклади: fünf, der Schlüssel (шлю́сель).</div><div class=\"kurss-example\">ö вимовляють із заокругленими губами, намагаючись вимовити е: der Löffel.</div><div class=\"kurss-example\">Подвоєний голосний позначає довгий голосний: leer (ле́р).</div><div class=\"kurss-example\">Дифтонг eu вимовляють як ой: neun (нойн).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Граматика та пояснення</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Наголошений префікс складного дієслова в теперішньому часі відокремлюється від дієслова й стоїть у кінці речення.</div><div class=\"kurss-example\">Приклади: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Числівник «один» має форми всіх трьох родів, якщо вживається з іменником: у чоловічому роді ein, у жіночому eine, у середньому ein.</div><div class=\"kurss-example\">Приклади: ein Schüler — один учень; eine Schülerin — одна учениця; ein Kind — одна дитина.</div><div class=\"kurss-example\">Числівники: eins, zwei, drei, vier (фі́р), fünf, sechs (зекс), sieben (зі́бен), acht, neun (нойн), zehn (це́н).</div><div class=\"kurss-example\">Дієслово-зв'язка в німецькій мові має форми однини й множини: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Вказівне слово das у німецькій мові має одну форму для всіх родів і чисел, так само як українське «це» в реченнях на зразок «це молоток».</div><div class=\"kurss-example\">Приклади: це молоток — das ist ein Hammer; це голка — das ist eine Nadel; це молотки — das sind Hämmer; це голки — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — віз і der Schlitten — сани в німецькій мові вживаються в однині й у множині, хоча українське слово «сани» має лише форму множини.</div><div class=\"kurss-example\">Іменники чоловічого й середнього роду із закінченням -er, -el, -en у множині часто не отримують закінчення.</div><div class=\"kurss-example\">Приклади: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Іменники жіночого роду із закінченням -el, -er у множині отримують -n.</div><div class=\"kurss-example\">Приклади: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Винятки: die Mutter (мати) — die Mütter (матері); die Tochter (дочка) — die Töchter (дочки).</div><div class=\"kurss-example\">Неозначений артикль не має множини: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">У розповідному реченні присудок-дієслово стоїть на другому місці: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переклади</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 6: картка для перекладу\"><span class=\"lesson1-training-progress\">Урок 6 · Переклади: 1 / 21</span><span class=\"lesson1-training-text\">Пауль бере олівець і малює.</span></button><p class=\"lesson1-training-hint\">Натисни на картку, щоб побачити переклад німецькою. Після відповіді наступне натискання покаже наступну картку.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Урок 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, знахідний відмінок, sitzen, fragen і суфікс -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (зіцен) — сидіти</div>\n        <div class=\"kurss-example\">fragen (фра́ґен) — питати</div>\n        <div class=\"kurss-example\">der Lehrer (де́р ле́рер) — учитель</div>\n        <div class=\"kurss-example\">gut (ґу́т) — добре</div>\n        <div class=\"kurss-example\">wen (ве́н) — кого</div>\n        <div class=\"kurss-example\">loben — хвалити</div>\n        <div class=\"kurss-example\">der Schüler (шю́лер) — учень</div>\n        <div class=\"kurss-example\">klein — малий</div>\n        <div class=\"kurss-example\">groß (ґро́с) — великий</div>\n        <div class=\"kurss-example\">die Lehrerin — учителька</div>\n        <div class=\"kurss-example\">die Schülerin — учениця</div>\n        <div class=\"kurss-example\">schlecht (шлехт) — погано</div>\n        <div class=\"kurss-example\">tadeln — ганити</div>\n        <div class=\"kurss-example\">oder (о́дер) — або</div>\n        <div class=\"kurss-example\">das Kind (кінт) — дитина</div>\n        <div class=\"kurss-example\">artig (а́ртіх) — чемний</div>\n        <div class=\"kurss-example\">die Mutter — мати</div>\n        <div class=\"kurss-example\">lieben (лі́бен) — любити</div>\n        <div class=\"kurss-example\">der Vater (фа́тер) — батько</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz означає подвоєне z, яке вимовляють як ц: sitzen (зіцен).</div>\n        <div class=\"kurss-example\">v у німецьких словах вимовляють як ф: der Vater (фа́тер).</div>\n        <div class=\"kurss-example\">ß називають есцет і вимовляють як українське с: groß (ґро́с), weiß (вайс).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Називний і знахідний відмінки</h4><div class=\"lesson1-grammar-note\">В українській мові називний відмінок відповідає на питання хто? що?, а знахідний відмінок відповідає на питання кого? що?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">У німецькій мові в називному відмінку ставлять питання wer? для осіб і was? для предметів.</div><div class=\"kurss-example\">У знахідному відмінку ставлять питання wen? для осіб і was? для предметів.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Зміна артиклів у знахідному відмінку</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + знахідний відмінок</h4><div class=\"lesson1-grammar-note\">Дієслово fragen у німецькій мові вимагає знахідного відмінка.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Суфікс -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Багато іменників жіночого роду утворюють за допомогою суфікса -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Місце дієслова</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">У розповідному реченні дієслово стоїть на другому місці.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переклади</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 5: картка для перекладу\"><span class=\"lesson1-training-progress\">Урок 5 · Переклади: 1 / 16</span><span class=\"lesson1-training-text\">Кого любить батько?</span></button><p class=\"lesson1-training-hint\">Натисни на картку, щоб побачити переклад німецькою. Після відповіді наступне натискання покаже наступну картку.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Урок 4</h3>\n            <p class=\"kurss-lesson-intro\">Знахідний відмінок, nehmen, hinlegen, hinausgehen і прикметники.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (не́мен) — брати</div><div class=\"kurss-example\">er nimmt (німт) — він бере</div><div class=\"kurss-example\">der Federhalter (де́р фе́дергальтер) — ручка для пера</div><div class=\"kurss-example\">einen Federhalter — ручку для пера</div><div class=\"kurss-example\">zeigen — показувати</div><div class=\"kurss-example\">schwarz (шварц) — чорний</div><div class=\"kurss-example\">weiß (вайс) — білий</div><div class=\"kurss-example\">die Feder (ді́ фе́дер) — перо</div><div class=\"kurss-example\">eine Feder — перо</div><div class=\"kurss-example\">spitz (шпіц) — гострий, загострений</div><div class=\"kurss-example\">hinlegen — покласти</div><div class=\"kurss-example\">legt hin — кладе</div><div class=\"kurss-example\">das Mädchen (ме́тхен) — дівчинка</div><div class=\"kurss-example\">das Messer — ніж</div><div class=\"kurss-example\">ein Messer — ніж</div><div class=\"kurss-example\">scharf — гострий</div><div class=\"kurss-example\">stumpf (штумпф) — тупий</div><div class=\"kurss-example\">dann — тоді, потім</div><div class=\"kurss-example\">hinaus — надвір, назовні</div><div class=\"kurss-example\">hinausgehen — вийти, іти надвір</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Закінчення -en, -er, -el ненаголошені, тому e в них ледь чутно: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h у німецькій мові може бути як звуком, так і знаком довготи попереднього голосного.</div><div class=\"kurss-example\">Якщо h позначає довготу, його не вимовляють як звук: nehmen (не́мен).</div><div class=\"kurss-example\">Якщо після голосного йде лише один приголосний, голосний вимовляють довго: die (ді́) Feder (фе́дер), den (де́н).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Знахідний відмінок</h4><div class=\"lesson1-grammar-note\">У жіночому та середньому роді знахідний відмінок збігається з називним. Змінюється лише чоловічий рід.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Займенники</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — чоловічий рід</div><div class=\"kurss-example\">sie — жіночий рід</div><div class=\"kurss-example\">es — середній рід</div><div class=\"kurss-example\">у множині — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Відокремлювані дієслова</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Прикметники</h4><div class=\"lesson1-grammar-note\">Якщо прикметник у реченні є іменною частиною присудка, він не змінюється ні за родами, ні за числами.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Заперечення з nicht</h4><div class=\"lesson1-grammar-note\">Якщо nicht заперечує прикметник, воно стоїть перед заперечуваним словом.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Іменники із суфіксами -chen і -lein належать до середнього роду: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переклади</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 4: картка для перекладу\"><span class=\"lesson1-training-progress\">Урок 4 · Переклади: 1 / 16</span><span class=\"lesson1-training-text\">Дівчинка бере ручку для пера.</span></button><p class=\"lesson1-training-hint\">Натисни на картку, щоб побачити переклад німецькою. Після відповіді наступне натискання покаже наступну картку.</p></div></div></details>",
  "kurssLesson3": "            <h3>Урок 3</h3>\n            <p class=\"kurss-lesson-intro\">Третій урок: діалоги, слова, вимова, граматика й переклад.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — хто</div><div class=\"kurss-example\">was — що</div><div class=\"kurss-example\">hier — тут</div><div class=\"kurss-example\">dort — там</div><div class=\"kurss-example\">der Tisch — стіл</div><div class=\"kurss-example\">ein Tisch — стіл</div><div class=\"kurss-example\">die Bank — лава</div><div class=\"kurss-example\">eine Bank — лава</div><div class=\"kurss-example\">liegen — лежати</div><div class=\"kurss-example\">liegt hier ein Buch? — чи тут лежить / є книжка?</div><div class=\"kurss-example\">das Buch — книжка</div><div class=\"kurss-example\">ein Buch — книжка</div><div class=\"kurss-example\">hängen — висіти</div><div class=\"kurss-example\">das Bild — картина</div><div class=\"kurss-example\">ein Bild — картина</div><div class=\"kurss-example\">die Tafel — дошка</div><div class=\"kurss-example\">eine Tafel — дошка</div><div class=\"kurss-example\">wie — який, яка</div><div class=\"kurss-example\">ist — є</div><div class=\"kurss-example\">dick — товстий, грубий</div><div class=\"kurss-example\">das Heft — зошит</div><div class=\"kurss-example\">ein Heft — зошит</div><div class=\"kurss-example\">dünn — тонкий, худий</div><div class=\"kurss-example\">niedrig — низький</div><div class=\"kurss-example\">hoch — високий</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Довгий звук і в німецькій мові позначають буквосполученням ie: liegen (лі́ґен), hier (гі́р), wie (ві́).</div><div class=\"kurss-example\">ck позначає подвоєне k: dick (дікк).</div><div class=\"kurss-example\">У прикметниках і прислівниках закінчення -ig звучить як легке -ich: niedrig (ні́дріх).</div><div class=\"kurss-example\">Якщо в закінченні -ig далі йде e, тобто -ige, то g вимовляють як чіткий звук ґ: niedrige (ні́дріґе) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Підмет</h4><div class=\"lesson1-grammar-note\">Підмет у німецькій мові відповідає на питання wer? / was? і стоїть у називному відмінку.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Питанням wer? запитують про осіб.</div><div class=\"kurss-example\">Питанням was? запитують про предмети.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Артиклі</h4><div class=\"lesson1-grammar-note\">У німецькій мові іменники мають 3 роди: чоловічий, жіночий і середній. Перед іменником зазвичай стоїть слівце, яке називають артиклем. Це слівце не перекладають.</div><h5 class=\"lesson2-subtitle\">Означений артикль</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">чоловічий рід — der</div><div class=\"kurss-example\">жіночий рід — die</div><div class=\"kurss-example\">середній рід — das</div><div class=\"kurss-example\">У множині означений артикль для всіх трьох родів однаковий: die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Неозначений артикль</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">чоловічий рід — ein</div><div class=\"kurss-example\">жіночий рід — eine</div><div class=\"kurss-example\">середній рід — ein</div><div class=\"kurss-example\">Неозначений артикль не має множини.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Власні назви</h4><div class=\"lesson1-grammar-note\">Перед власними назвами артикль не вживають.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Місце дієслова</h4><div class=\"lesson1-grammar-note\">У розповідному реченні дієслово стоїть на другому місці.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Німецькою про предмети, розташовані вертикально, кажуть, що предмет стоїть:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Про предмети в горизонтальному положенні кажуть, що вони лежать:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Предмети можуть також висіти:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переклади</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 3: картка для перекладу\"><span class=\"lesson1-training-progress\">Урок 3 · Переклади: 1 / 22</span><span class=\"lesson1-training-text\">Ти рахуєш?</span></button><p class=\"lesson1-training-hint\">Натисни на картку, щоб побачити переклад німецькою. Після відповіді наступне натискання покаже наступну картку.</p></div></div></details>",
  "kurssLesson7": "            <h3>Урок 7</h3>\n            <p class=\"kurss-lesson-intro\">Сьомий урок: наказовий спосіб, ввічлива форма звертання та множина.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Діалоги / речення</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — співати</div><div class=\"kurss-example\">singe — співай</div><div class=\"kurss-example\">singt — співайте</div><div class=\"kurss-example\">singen Sie — співайте</div><div class=\"kurss-example\">das Lied (дас лі́т) — пісня</div><div class=\"kurss-example\">Sie — Ви</div><div class=\"kurss-example\">zählen — лічити</div><div class=\"kurss-example\">das Fräulein (фройлайн) — панночка</div><div class=\"kurss-example\">der Müller — мельник</div><div class=\"kurss-example\">öffnen — відчиняти</div><div class=\"kurss-example\">das Fenster (фенстер) — вікно</div><div class=\"kurss-example\">alle — усі</div><div class=\"kurss-example\">der Spiegel (шпі́ґель) — дзеркало</div><div class=\"kurss-example\">der Lappen — ганчірка, шмата</div><div class=\"kurss-example\">der Spaten — лопата</div><div class=\"kurss-example\">der Besen — мітла</div><div class=\"kurss-example\">die Schaufel — совок, лопатка</div><div class=\"kurss-example\">die Schüssel — миска</div><div class=\"kurss-example\">das Zimmer — кімната</div><div class=\"kurss-example\">das Ufer (у́фер) — берег</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp на початку слова або складу вимовляють як шп: der Spiegel (де́р шпі́ґель).</div><div class=\"kurss-example\">sch вимовляють як українське ш: die Schaufel (ді́ шауфель), die Schüssel (ді́ шюсель).</div><div class=\"kurss-example\">Дифтонг äu вимовляють як українське ой: das Fräulein (дас фройлайн).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Наказовий спосіб</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Наказовий спосіб у 2-й особі однини відповідає формі 2-ї особи однини дієслова без особового закінчення -st, до якої додають закінчення -e.</div><div class=\"kurss-example\">Приклади: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Дуже часто закінчення -e не вживають, якщо без нього форма наказового способу односкладова: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Наказовий спосіб у множині</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Форма наказового способу 2-ї особи множини збігається з формою 2-ї особи множини теперішнього часу, але вживається без займенника.</div><div class=\"kurss-example\">Приклади: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Ввічлива форма звертання з Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ввічлива форма звертання на «Ви» збігається з 3-ю особою множини. Займенник Sie пишуть з великої літери, і він стоїть після дієслова.</div><div class=\"kurss-example\">Приклади: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">У дієслові öffnen для легшої вимови в 2-й і 3-й особах однини та в 2-й особі множини між основою й закінченням вставляють e: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Вправа</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 7: картка вправи\"><span class=\"lesson1-training-progress\">Урок 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — питати</span></button><p class=\"lesson1-training-hint\">Торкнися картки, щоб побачити форми наказового способу.</p></div></div></details>",
  "kurssLesson1": "            <h3>Урок 1</h3>\n            <p class=\"kurss-lesson-intro\">Перший урок: дієслова в теперішньому часі, слова, вимова, граматика й переклад.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Дієслова в теперішньому часі</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Дієслова та їх відмінювання в теперішньому часі.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — приходити</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>я приходжу</span><span>du</span><strong>kommst</strong><span>ти приходиш</span><span>er / sie</span><strong>kommt</strong><span>він / вона приходить</span><span>wir</span><strong>kommen</strong><span>ми приходимо</span><span>ihr</span><strong>kommt</strong><span>ви приходите</span><span>sie / Sie</span><strong>kommen</strong><span>вони / Ви приходять</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — іти</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>я йду</span><span>du</span><strong>gehst</strong><span>ти йдеш</span><span>er / sie</span><strong>geht</strong><span>він / вона йде</span><span>wir</span><strong>gehen</strong><span>ми йдемо</span><span>ihr</span><strong>geht</strong><span>ви йдете</span><span>sie / Sie</span><strong>gehen</strong><span>вони / Ви йдуть</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — стояти</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>я стою</span><span>du</span><strong>stehst</strong><span>ти стоїш</span><span>er / sie</span><strong>steht</strong><span>він / вона стоїть</span><span>wir</span><strong>stehen</strong><span>ми стоїмо</span><span>ihr</span><strong>steht</strong><span>ви стоїте</span><span>sie / Sie</span><strong>stehen</strong><span>вони / Ви стоять</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — співати</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>я співаю</span><span>du</span><strong>singst</strong><span>ти співаєш</span><span>er / sie</span><strong>singt</strong><span>він / вона співає</span><span>wir</span><strong>singen</strong><span>ми співаємо</span><span>ihr</span><strong>singt</strong><span>ви співаєте</span><span>sie / Sie</span><strong>singen</strong><span>вони / Ви співають</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Приклади</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Слова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Приблизну вимову слів подано в дужках українськими літерами.<br>Це слід враховувати й у наступних уроках.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (ві́р) — ми</div><div class=\"kurss-example\">У слові «wir» літеру i вимовляють довго.</div><div class=\"kurss-example\">kommen (комен) — приходити</div><div class=\"kurss-example\">gehen (ґе́-ен) — іти</div><div class=\"kurss-example\">stehen (ште́-ен) — стояти</div><div class=\"kurss-example\">singen (зінґен) — співати</div><div class=\"kurss-example\">du (ду́) kommst — ти приходиш</div><div class=\"kurss-example\">er (е́р) kommt — він приходить</div><div class=\"kurss-example\">sie (зі́) kommt — вона приходить</div><div class=\"kurss-example\">wer (ве́р) — хто?</div><div class=\"kurss-example\">ja (я́) — так</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Вимова</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Правильну вимову слів, записану українськими літерами, подано в уроках.</div><div class=\"kurss-example\">Wir (ві́р) — ми. У слові wir звук і завжди вимовляють довго.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Граматика</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Інфінітив</h4><div class=\"lesson1-grammar-note\">Основна форма дієслова. Зазвичай інфінітив закінчується на -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Закінчення теперішнього часу</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Відкинь <span class=\"lesson1-ending-accent\">-en</span> від основної форми дієслова й додай закінчення.</strong></p><p>Приклад: kommen → komm + закінчення</p><div class=\"lesson1-ending-process\" aria-label=\"Як утворюються форми теперішнього часу\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>основна форма</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>відкинь <span class=\"lesson1-ending-accent\">-en</span></strong><span>залишається корінь</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>корінь</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>додай закінчення</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Приклади</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Питальні речення</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>У німецькому питальному реченні дієслово зазвичай переходить на перше місце.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Українською:<br>Ти приходиш.<br>Чи ти приходиш?</div><div class=\"kurss-example\">Німецькою:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — ти приходиш<br>kommst du? — чи ти приходиш?</div><div class=\"kurss-example\">er singt — він співає<br>singt er? — чи він співає?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Розрізнення осіб</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — він приходить</div><div class=\"kurss-example\">sie kommt — вона приходить</div><div class=\"kurss-example\">sie kommen — вони приходять</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Переклади</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Урок 1: тренувальна картка\">\n                    <span class=\"lesson1-training-progress\">Урок 1 · Переклади: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Ти приходиш?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Натисни на картку, щоб побачити переклад німецькою. Після відповіді наступне натискання покаже наступну картку.</p>\n                </div>\n              </div>\n            </details>"
};

